import type { CiGuardianConfig } from '../../config/types.js';

export const BITBUCKET_PIPELINE_PATH = 'bitbucket-pipelines.yml';

export function renderBitbucketPipeline(config: CiGuardianConfig, defaultBranch = 'main'): string {
  const lines = [
    '# Generated by @agnotic/ci-guardian. Do not edit directly.',
    '# Run quality checks identically locally and in Bitbucket Pipelines.',
    'image: node:20',
    '',
    'definitions:',
    '  caches:',
    '    npm: ~/.npm',
    '',
    'pipelines:',
    '  pull-requests:',
    "    '**':",
    '      - step:',
    '          name: CI Guardian Quality Gate',
    '          caches:',
    '            - npm',
    '          script:',
    '            - npm ci',
    '            - npx ci-guardian run',
    '          artifacts:',
    `            - ${config.report.path}`,
    '  branches:',
    `    ${defaultBranch}:`,
    '      - step:',
    '          name: CI Guardian Quality Gate',
    '          caches:',
    '            - npm',
    '          script:',
    '            - npm ci',
    '            - npx ci-guardian run',
    '          artifacts:',
    `            - ${config.report.path}`,
    '',
  ];
  return lines.join('\n');
}
